package com.personal.jobagent.email;
import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/v1/emails") public class EmailController {private final EmailIntelligenceService s;public EmailController(EmailIntelligenceService s){this.s=s;} public record IngestRequest(String messageId,String from,String to,String subject,String body,Instant receivedAt){} public record VerifyRequest(UUID emailId,UUID sessionId,String expectedDomain){} @PostMapping("/ingest") public EmailIntelligenceService.IngestResult ingest(@RequestBody IngestRequest r){return s.ingest(r.messageId(),r.from(),r.to(),r.subject(),r.body(),r.receivedAt()==null?Instant.now():r.receivedAt());} @PostMapping("/verification/extract") public Map<String,Object> extract(@RequestBody VerifyRequest r){return s.extractVerification(r.emailId(),r.sessionId(),r.expectedDomain()).orElse(Map.of("accepted",false));} @PostMapping("/verification/{id}/resolve") public Map<String,Object> resolve(@PathVariable UUID id){return Map.of("accepted",true,"value",s.resolve(id));} }